INSERT INTO `mail_body` VALUES ('8', '10', '1', 'HR02', '1595922882', '郭林鹏调薪通知', '郭林鹏：\r\n\r\n        您好，基于您的工作业绩与贡献，公司决定对您加薪3950.00元，原薪资总额为16190.00元（不包括绩效薪资上下浮动部分），加薪后总额为20140.00元（不包括绩效薪资上下浮动部分）,2020年08月01日生效。\r\n    \r\n        请严格遵守薪资保密原则，不与公司其他任何部门及员工讨论薪资信息，同时不得透露个人薪资信息，否则将视为严重违反劳动纪律，违反保守商业秘密协议，公司保留即时撤销加薪和解除劳动合同的权利。\r\n    \r\n        感谢您的付出，希望未来能一起努力，为公司创造更好的业绩。\r\n    \r\n    \r\n                                                              \r\n                                                        行政人力资源部\r\n    \r\n        \r\n                                                     2020年07月28日', '', '', '');
