INSERT INTO `mail_body` VALUES ('902813', '161873', '0', 'INHE-0697', '1597042742', '', '曾经理，请查收以下信息及附件， 1.刘海波 2013年毕业于青岛理工大学（统招一本），29岁，毕业后从事消费类电子产品结构设计7年，熟悉消费类电子产品结构设计开发流程，熟悉Proe，Auto-CAD绘图软件及办公软件，熟悉塑胶注塑成型等工艺，目前已经离职，可以快速到岗，薪资期望为16K左右，可约面试时间为周三或周四； 2.付良宵 2012年毕业于沈阳理工大学（统招二本），30岁，毕业后一直从事新产品开发和结构设计相关工作，主要产品是风扇和电池，对塑胶模具了解，目前在职，由于公司规模小觉得不正规而打算看新机会，可以快速到岗，薪资期望为10K以上，如合适可以尽快约面试； 3.周飞 1999年毕业于南昌大学（211院校），42岁，毕业后一直从事产品结构设计相关工作，自述对塑胶模具非常了解，经验丰富，目前已经离职， 离职原因是波顿集团的产品为电子烟，受国家政策影响订单下滑加上公司人员结构调整，期望薪资为20-25K，低于20K不考虑，如合适周三下午可约面试。以上请知悉，详细信息请查阅附件，并请回复推荐结果。', '', '', '');
